// node savesvg.mjs <html> <out.svg> <regex that the svg tag must match>
// Saves the first inline <svg> whose text matches the regex, with currentColor -> fill black.
import { readFileSync, writeFileSync } from "node:fs";
const [, , file, out, pat] = process.argv;
const html = readFileSync(file, "utf8");
const re = new RegExp(pat);
for (const m of html.matchAll(/<svg[\s\S]*?<\/svg>/g)) {
  if (!re.test(m[0])) continue;
  let s = m[0].replace(/class="[^"]*"/g, "");
  if (!/xmlns=/.test(s)) s = s.replace("<svg", '<svg xmlns="http://www.w3.org/2000/svg"');
  writeFileSync(out, s);
  console.log("saved", out, s.length);
  process.exit(0);
}
console.log("no match");

