      <div style={{ position: "absolute", left: 140, top: 190, transform: `translateY(${lift}px)` }}>
        <div style={{ fontSize: 132, fontWeight: 300, letterSpacing: "-0.05em", lineHeight: 1.02 }}>
          <div><Words text="No crash." at={rel("No")} every={5} /></div>
