        {/* neatlogs */}
        <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 1080 }}>
          <div style={{ position: "absolute", left: 120, top: 110, display: "flex", alignItems: "center", gap: 22 }}>
            <PartnerLogo id="neatlogs" height={46} />
