import React from "react";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { C, inter, mono } from "../theme";
import { clamp, expo, ramp } from "../ui/motion";
import { useRel, PartnerLogo, Cta } from "../ui/kit";
import { Wall } from "../ui/Wall";
import { Words } from "../ui/Words";

const PARTNERS = [
  { id: "neatlogs" as const, h: 34, note: "traces + read-back" },
  { id: "entire" as const, h: 30, note: "checkpoints + provenance" },
  { id: "cfoai" as const, h: 38, note: "business plan" },
  { id: "0g" as const, h: 38, note: "0G Compute · Claude" },
  { id: "crustdata" as const, h: 32, note: "real data + market" },
];

/** The wall, whole. Break it first. The tools it was built with. */
export const Close: React.FC = () => {
  const f = useCurrentFrame();
  const rel = useRel("close");
  const tName = rel("Bulwark.");
  const word = interpolate(f, [tName - 4, tName + 14], [0, 1], { ...clamp, easing: expo });
  const tWall = rel("watching.") + 20;
  return (
    <AbsoluteFill style={{ background: C.paper, fontFamily: inter, color: C.ink }}>
      <AbsoluteFill style={{ alignItems: "center", paddingTop: 170 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 34 }}>
          <Wall size={170} build={[-10, tName + 4]} />
          <div style={{ fontSize: 160, fontWeight: 500, letterSpacing: "-0.06em", opacity: word, clipPath: `inset(0 ${(1 - word) * 100}% 0 0)` }}>Bulwark</div>
        </div>
        <div style={{ marginTop: 24, fontSize: 96, fontWeight: 300, letterSpacing: "-0.045em" }}>
          <Words text="Break it first." at={rel("Break")} every={5} accent={{ "first.": C.crash }} serifScale={1.15} />
        </div>
        <div style={{ marginTop: 14, fontSize: 40, fontWeight: 300, letterSpacing: "-0.025em", color: C.ink2 }}>
          <Words text="Agents you can trust to run without you watching." at={rel("Agents")} every={3} />
        </div>
        <div style={{ marginTop: 40, opacity: ramp(f, rel("Agents") + 20, rel("Agents") + 34) }}>
          <Cta>github.com/mrnetwork0001/Bulwark</Cta>
        </div>
